// Cross-language interop: the *web client's* crypto code must reproduce every
// vector in design/test-vectors/lan.json (generated by the Dart code).
// Run: node scripts/lan-vectors.mjs
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import * as L from '../webapp/lan-crypto.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const v = JSON.parse(readFileSync(path.join(here, '..', 'design', 'test-vectors', 'lan.json'), 'utf8'));
const p = v.primitives;
const hs = v.handshakes;
const ok = (a, b, label) => assert.equal(L.hex(a), b, label);

assert.equal(L.CODE_ALPHABET, v.constants.codeAlphabet);
assert.equal(L.KDF_ITERATIONS, v.constants.kdfIterations);
assert.equal(L.normalizeCode('abcd-efgh'), 'ABCDEFGH');
assert.throws(() => L.normalizeCode('ABCD0FGH'));

ok(L.sha256Bytes(L.unhex(p.sha256.input)), p.sha256.sha256, 'sha256');
ok(L.hmacSha256(L.unhex(p.hmacSha256.key), L.unhex(p.hmacSha256.message)), p.hmacSha256.mac, 'hmac');
ok(L.hkdfSha256(L.unhex(p.hkdfSha256.ikm), L.unhex(p.hkdfSha256.salt), L.unhex(p.hkdfSha256.info)), p.hkdfSha256.okm, 'hkdf');
ok(L.pbkdf2Sha256(L.unhex(p.pbkdf2Sha256.password), L.unhex(p.pbkdf2Sha256.salt)), p.pbkdf2Sha256.dk, 'pbkdf2');

const privA = L.unhex(p.x25519.alicePrivate);
const privB = L.unhex(p.x25519.bobPrivate);
const pubA = L.unhex(p.x25519.alicePublic);
const pubB = L.unhex(p.x25519.bobPublic);
ok(L.x25519Public(privA), p.x25519.alicePublic, 'x25519 public');
ok(L.x25519Shared(privA, pubB), p.x25519.shared, 'x25519 shared');
assert.deepEqual(L.x25519Shared(privB, pubA), L.x25519Shared(privA, pubB));

ok(L.seal(L.unhex(p.chacha20poly1305.key), L.unhex(p.chacha20poly1305.nonce),
  L.unhex(p.chacha20poly1305.aad), L.unhex(p.chacha20poly1305.plaintext)),
  p.chacha20poly1305.sealed, 'chacha20poly1305');
assert.deepEqual(
  L.open(L.unhex(p.chacha20poly1305.key), L.unhex(p.chacha20poly1305.nonce),
    L.unhex(p.chacha20poly1305.aad), L.unhex(p.chacha20poly1305.sealed)),
  L.unhex(p.chacha20poly1305.plaintext));

// ---- code mode ----
const c = hs.code;
const t = L.transcript(L.unhex(c.epcPublic), L.unhex(c.ephonePublic), c.sid);
ok(t, c.transcript, 'code transcript');
const ck = L.codeKey(c.code, t);
ok(ck, c.codeKey, 'code key');
ok(L.proof(ck, 'pc', t), c.proofPc, 'proof_pc');
ok(L.proof(ck, 'phone', t), c.proofPhone, 'proof_phone');
const z = L.x25519Shared(L.unhex(c.epcPrivate), L.unhex(c.ephonePublic));
ok(z, c.z, 'code z');
const sk = L.sessionKey(z, t);
ok(sk, c.sessionKey, 'code session key');

const env = c.envelope;
const en = L.nonce(env.direction, env.counter);
const ea = L.aad(c.sid, env.direction, env.counter);
assert.equal(en.length, 12, 'nonce must be 12 bytes');
ok(en, env.nonce, 'envelope nonce');
ok(ea, env.aad, 'envelope aad');
ok(L.seal(sk, en, ea, L.unhex(env.plaintext)), env.sealed, 'envelope');
assert.deepEqual(L.open(sk, en, ea, L.unhex(env.sealed)), L.unhex(env.plaintext));

// ---- QR mode ----
const q = hs.qr;
const qt = L.transcript(L.unhex(q.epcPublic), L.unhex(q.ephonePublic), q.sid);
ok(qt, q.transcript, 'qr transcript');
const qk = L.qrKey(L.unhex(q.s), qt);
ok(qk, q.qrKey, 'qr key');
ok(L.proof(qk, 'phone', qt), q.proofPhone, 'qr proof_phone');
ok(L.sessionKey(L.x25519Shared(L.unhex(q.epcPrivate), L.unhex(q.ephonePublic)), qt),
  q.sessionKey, 'qr session key');

// ---- trusted reconnect ----
const tr = hs.trusted;
const tn = L.unhex(tr.nonce);
const tt = L.trustedTranscript(L.unhex(tr.epcPublic), L.unhex(tr.ephonePublic), tn);
ok(tt, tr.transcript, 'trusted transcript');
const ts = L.unhex(tr.deviceSecret);
ok(L.proof(ts, 'pc', tt, tn), tr.proofPc, 'trusted proof_pc');
ok(L.proof(ts, 'phone', tt, tn), tr.proofPhone, 'trusted proof_phone');
const tz = L.x25519Shared(L.unhex(tr.epcPrivate), L.unhex(tr.ephonePublic));
ok(L.trustedSessionKey(tz, tt, ts), tr.sessionKey, 'trusted session key');

// ---- rejection / constant time ----
const r = v.rejection;
assert.throws(() => L.open(L.unhex(r.sessionKey), L.nonce(r.direction, r.counter),
  L.aad(r.sid, r.direction, r.counter), L.unhex(r.sealed)));
assert.equal(L.constantTimeEquals(new Uint8Array([1, 2, 3]), new Uint8Array([1, 2, 4])), false);
assert.equal(L.constantTimeEquals(new Uint8Array([1, 2, 3]), new Uint8Array([1, 2, 3])), true);

console.log(`LAN interop: ${Object.keys(p).length} primitives + 3 handshakes + rejection OK (${v.version})`);
